using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Unity.Profiling;
using SporeGobbo.Geometry;
using SporeGobbo.Geometry.Preview;
namespace SporeGobbo.CampCandidate.Preview
{
 public sealed class Stage57Benchmark:MonoBehaviour
 {
  [Serializable]public class Frame{public string phase;public double interval,display,decorations;public long allocation;public int resident,meshes,revision;public bool ready;}
  [Serializable]public class Event{public string name;public double ms;public string result;}
  [Serializable]public class Resource{public string name;public long managed,unity;public int meshes,resident;}
  [Serializable]public class Result{public string error="",hardware;public List<Frame> frames=new List<Frame>();public List<Event> events=new List<Event>();public List<Resource> resources=new List<Resource>();public List<string> checks=new List<string>();}
  Stage57Preview camp;string output;Result result=new Result();ProfilerRecorder alloc;
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int n=Array.IndexOf(args,"-stage57Output");if(n<0)yield break;output=args[n+1];Directory.CreateDirectory(output);camp=GetComponent<Stage57Preview>();camp.Initialize();camp.automation=true;camp.showPanel=false;camp.Live.automation=true;Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;result.hardware=SystemInfo.processorType+" / "+SystemInfo.graphicsDeviceName+" / "+SystemInfo.graphicsDeviceType;alloc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");camp.Session.Committed+=b=>RecordEvent("mesh-batch:"+b.Reason,camp.MutationMs,"accepted cells="+b.Cells.Count);RecordEvent("definition",camp.DefinitionMs,"complete authored base");RecordEvent("initialization",camp.ResetMs,"setup excludes streaming wait");yield return Settle();ResourceSample("initial");for(int probe=0;probe<3;probe++){var bytes=new byte[1048576];bytes[0]=1;yield return null;RecordEvent("allocation-probe-bytes",alloc.Valid?alloc.LastValue:-1,"completed-frame observation for 1MiB allocation; value is bytes");GC.KeepAlive(bytes);}yield return Capture("01-intro-approach");camp.Go("fire");yield return Settle();yield return Capture("02-fire-initial62");foreach(string id in new[]{"run.departure","bones","squad"}){var m=camp.Session.Definition.Marker(id);var a=camp.ScreenPoint(m.Anchor);var approach=camp.ScreenPoint(m.Interaction);RecordEvent("composition:"+id,0,$"anchor pixels {a}; approach pixels {approach}; Fire position {camp.Live.Position}");}camp.SetFraming(1);yield return Capture("03-fire-comparison57");camp.SetFraming(0);yield return Frames("camera-warm",180);
   camp.returnBuddies=1;long t=System.Diagnostics.Stopwatch.GetTimestamp();camp.FakeReturn();RecordEvent("first-return",StreamingGeometry.Elapsed(t),camp.Status);camp.Go("fire");yield return Settle();Validate("first-buddy");yield return Capture("04-first-buddy-fire");Probe("dorm-first-entrance",camp.Session.Definition.Bedrooms[0].Entrance);Probe("squad-approach",camp.Session.Definition.Marker("squad").Interaction);
   camp.DigBedrooms();camp.ConstructionClock.FinishCurrent=true;int initialRevision=camp.Session.Revision,guard=0;bool firstCapture=false;while(camp.Constructing&&guard++<10000){double tick=Time.realtimeSinceStartupAsDouble;camp.TickResidents(Time.unscaledDeltaTime);yield return null;RecordFrame("first-excavation",(Time.realtimeSinceStartupAsDouble-tick)*1000);CheckBound();if(!firstCapture&&camp.Session.Revision>initialRevision+5){firstCapture=true;yield return Settle();Probe("dorm-worker-during-excavation",camp.Session.Construction.Worker.Position);yield return Capture("05-fire-first-excavation");}}
   Check(camp.Session.Established==1,"First authorized room completes");Validate("first-room");yield return Capture("06-fire-one-bed");
   t=System.Diagnostics.Stopwatch.GetTimestamp();camp.ConstructionClock.BuildDorm=true;camp.ConstructionClock.BuildTarget=5;yield return BuildTo(5);RecordEvent("build-five-wall-time",StreamingGeometry.Elapsed(t),"real elapsed paced multi-frame authorized operations");Validate("five-beds");yield return Capture("07-fire-five-beds");camp.ConstructionClock.BuildTarget=10;camp.ConstructionClock.BuildDorm=true;t=System.Diagnostics.Stopwatch.GetTimestamp();yield return BuildTo(10);RecordEvent("build-ten-from-five-wall-time",StreamingGeometry.Elapsed(t),"real elapsed paced multi-frame authorized operations");Validate("ten-beds");yield return Capture("08-fire-ten-beds");ResourceSample("grown");camp.showReservations=true;yield return Capture("09-fire-future-reservations");camp.showReservations=false;
   camp.Session.BuddyDied();Check(camp.Session.FirstDeath,"Bones interaction independent first-death gate");camp.Go("bones");yield return Settle();camp.categoryOverlay=true;yield return Capture("10-bones-arrival-terrain");camp.categoryOverlay=false;Validate("bones-unlocked");camp.Session.AddBuddy();Check(camp.Session.Residents[camp.Session.Residents.Count-1].Slot==1,"Vacancy reused without new excavation");
   t=System.Diagnostics.Stopwatch.GetTimestamp();camp.Session.Advance();RecordEvent("shop-inspection",StreamingGeometry.Elapsed(t),"preview eligibility; no merchant");Check(camp.Session.ShopInspected&&!camp.Session.FightInspected,"Shop inspection precedes Pit");camp.Go("shop.reserved");yield return Capture("11-shop-option-a");t=System.Diagnostics.Stopwatch.GetTimestamp();camp.Session.Advance();RecordEvent("pit-inspection",StreamingGeometry.Elapsed(t),"finite existing reservation-opening simulation");Validate("fully-open-public");camp.Go("fight.reserved");yield return Capture("12-pit-reservation");camp.showReservations=true;yield return Capture("13-pit-neighborhood");camp.showReservations=false;camp.Go("fire");yield return Capture("14-fire-open-public");camp.Session.Recover();yield return Frames("grown-camera-travel",360,true);
   for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.returnBuddies=2;camp.FakeReturn();RecordEvent("repeated-return-"+i,StreamingGeometry.Elapsed(t),camp.Status);yield return Settle();}Check(Type.GetType("GameState, Assembly-CSharp").GetProperty("Instance").GetValue(null)==null,"No GameState registration");Check(Type.GetType("DiggableTerrainService, Assembly-CSharp").GetProperty("Active").GetValue(null)==null,"No production terrain registration");
   camp.shopOption=1;camp.ResetTest(0);camp.Go("shop.reserved");yield return Capture("15-shop-option-b");camp.shopOption=0;for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.ResetTest(0);RecordEvent("reset-"+i,StreamingGeometry.Elapsed(t),"new deterministic session");yield return Settle();ResourceSample("reset-"+i);}camp.Go("fire");camp.showPanel=true;camp.advanced=true;yield return Capture("16-testing-controls");File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));alloc.Dispose();Application.Quit(result.error==""?0:1);
  }
  IEnumerator BuildTo(int target){int guard=0;while((camp.Session.Established<target||camp.Constructing)&&guard++<20000){double t=Time.realtimeSinceStartupAsDouble;camp.TickResidents(Time.unscaledDeltaTime);yield return null;RecordFrame("accelerated-dorm",(Time.realtimeSinceStartupAsDouble-t)*1000);CheckBound();}camp.ConstructionClock.BuildDorm=false;Check(camp.Session.Established==target,"Authorized accelerated target "+target+" / "+camp.ConstructionClock.Status);yield return Settle();}
  void CheckBound(){if(camp.ConstructionClock.LastTicks>8||camp.ConstructionClock.LastBatches>1)Check(false,"Construction frame bounds");}
  void Validate(string state){var fire=camp.Session.Definition.Marker("fire").Interaction;foreach(var m in camp.Session.Definition.Markers)if(camp.Session.Active(m.Gate)||m.Id=="bones"||m.Id=="squad"||m.Id=="shop.reserved")Check(camp.Session.Route(fire,m.Interaction,3).Count>0,state+" three-cell approach "+m.Id);foreach(var room in camp.Session.Definition.Bedrooms)Check(camp.Session.Route(fire,room.Entrance,3).Count>0,state+" dorm entrance "+room.Id);}
  void Probe(string name,Point2 p){
   var screen=camp.ScreenPoint(p);bool inside=screen.x>24&&screen.x<Screen.width-24&&screen.y>24&&screen.y<Screen.height-24;
   int clear=0,total=15;for(int y=0;y<3;y++)for(int x=0;x<5;x++){var q=camp.Live.Snapshot.Project(new Point2(p.X+(x-2)*.4,p.Y-y*.5));if(!Covered(q))clear++;}
   RecordEvent("screen-proof:"+name,0,$"logical=({p.X:F2},{p.Y:F2}); screen=({screen.x:F1},{screen.y:F1})/{Screen.width}x{Screen.height}; clear wall/lip samples={clear}/{total}; centerWidth={camp.Live.settings.centerWidth}; coverage={camp.Live.settings.coverage}; anchor={camp.Live.settings.anchor}; wallHeight={camp.Live.settings.wallHeight}");
   Check(inside&&clear>=5,name+" within normal Fire viewport with readable wall-clear samples");
  }
  bool Covered(Point2 p){foreach(var c in camp.Live.Stream.Resident.Values)foreach(var d in c.Layers)if(d.Layer==PreviewLayer.Faces||d.Layer==PreviewLayer.Lips){for(int i=0;i<d.Indices.Count;i+=3){var a=Resolve(d,d.Indices[i]);var b=Resolve(d,d.Indices[i+1]);var z=Resolve(d,d.Indices[i+2]);double ab=Cross(a,b,p),bc=Cross(b,z,p),ca=Cross(z,a,p);if((ab>1e-7&&bc>1e-7&&ca>1e-7)||(ab< -1e-7&&bc< -1e-7&&ca< -1e-7))return true;}}return false;}
  Point2 Resolve(PreviewMeshData d,int index){var v=d.LogicalVertices[index];if(v.WallSampleIndex<0)return camp.Live.Snapshot.Project(v.Logical);var w=WallGeometry.Project(d.WallSamples[v.WallSampleIndex],camp.Live.Snapshot,new WallSettings(camp.Live.settings.wallHeight,.22),camp.Live.settings.heightPolicy);return v.Role==GeometryVertexRole.WallBottom?w.Bottom:v.Role==GeometryVertexRole.ForegroundLip?w.Lip:w.Top;}
  static double Cross(Point2 a,Point2 b,Point2 c)=>(b.X-a.X)*(c.Y-a.Y)-(b.Y-a.Y)*(c.X-a.X);
  void Check(bool ok,string label){result.checks.Add((ok?"PASS ":"FAIL ")+label);if(!ok)result.error+=label+"; ";}
  void RecordEvent(string name,double ms,string detail){result.events.Add(new Event{name=name,ms=ms,result=detail});}
  IEnumerator Settle(){int i=0;do{yield return null;if(++i>3000){Check(false,"readiness timeout");yield break;}}while(!camp.Live.Ready);for(i=0;i<3;i++)yield return null;}
  IEnumerator Frames(string phase,int count,bool moving=false){for(int i=0;i<count;i++){double t=Time.realtimeSinceStartupAsDouble;if(moving){camp.TickResidents(Math.Min(.05,Time.unscaledDeltaTime));var p=camp.Live.Position;var delta=new Point2(Math.Sin(i*.03)*.05,Math.Cos(i*.03)*.05);var q=camp.Session.Move(Stage57Preview.P(p),delta,1);camp.Live.TeleportWithoutFocus(Stage57Preview.V(q));}yield return null;RecordFrame(phase,(Time.realtimeSinceStartupAsDouble-t)*1000);}}
  void RecordFrame(string phase,double interval){result.frames.Add(new Frame{phase=phase,interval=interval,display=camp.Live.DisplayMs,decorations=camp.DecorationMs,allocation=alloc.Valid?alloc.LastValue:-1,resident=camp.Live.Stream.Resident.Count,meshes=camp.Live.MeshCount+4,revision=camp.Session.Revision,ready=camp.Live.Ready});}
  IEnumerator Capture(string name){yield return Settle();camp.CameraStudy.Capture(output,name);while(camp.CameraStudy.CapturePending)yield return null;camp.CameraStudy.captureLabel=false;}
  void ResourceSample(string name){GC.Collect();result.resources.Add(new Resource{name=name,managed=GC.GetTotalMemory(true),unity=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),meshes=camp.Live.MeshCount+4,resident=camp.Live.Stream.Resident.Count});}
 }
}
